import { useEffect, useState } from "react";
import { Button, Table, Spinner, Alert } from "react-bootstrap";

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const token = localStorage.getItem('token');
  useEffect(() => {
  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError(null);

      const res = await fetch('http://localhost/api/comandes', {
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) throw new Error('Error al obtenir les comandes');

      const data = await res.json();
      setOrders(data.dades || []);
    } catch (err) {
      console.error(err);
      setError('Error al obtenir les comandes');
    } finally {
      setLoading(false);
    }
  };

  fetchOrders();
}, [token]);


  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-3">
        {error}
      </Alert>
    );
  }

  if (orders.length === 0) {
    return <p className="mt-3">No hi ha comandes disponibles</p>;
  }

  return (
    <div className="mt-4">
      <h2>Llista de Comandes</h2>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Client</th>
            <th>Proveïdor</th>
            <th>Tipus</th>
            <th>Data</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {orders.map((order) => (
            <tr key={order.id}>
              <td>{order.id}</td>
              <td>{order.client?.nom || 'Desconegut'}</td>
              <td>{order.proveidor?.nom || 'Desconegut'}</td>
              <td>{order.tipus}</td>
              <td>{new Date(order.data).toLocaleDateString('ca-ES')}</td>
              <td>
                <Button variant="warning" size="sm" className="me-2">
                  Editar
                </Button>
                <Button variant="danger" size="sm">
                  Eliminar
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </div>
  );
}

export default OrdersList;
